// ==UserScript==
// @name         SP·数据库 V
// @namespace    http://tampermonkey.net/
// @version      2.0.0
// @description  SillyTavern 数据库自动更新与交火模式索引管理脚本。
// @author       Cline (AI Assisted)
// @match        */*
// @grant        none
// @注释掉的require  https://code.jquery.com/jquery-3.7.1.min.js
// @注释掉的require  https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.js
// ==/UserScript==
(function () {
    'use strict';

    /**
     * shared/runtime-env.ts — 运行时环境检测
     *
     * 检测当前脚本运行在哪种环境中：
     * - 油猴脚本模式（Userscript）：运行在酒馆助手创建的 iframe 中，window.parent 指向酒馆主窗口
     * - 酒馆插件模式（Extension）：运行在酒馆主窗口中，window 就是酒馆主窗口
     *
     * 所有需要区分环境的代码都应通过此模块的函数来判断，而非自行检测。
     */
    /** 互斥检测全局标记键名 */
    const ACU_INSTANCE_FLAG = '__ACU_STAR_DB_III_LOADED__';
    /** 缓存检测结果，避免重复计算 */
    let _cachedMode = null;
    /**
     * 由插件入口在启动时调用，强制设置为插件模式。
     * 必须在任何其他模块访问 runtime-env 之前调用。
     */
    function _forceExtensionMode() {
        _cachedMode = "extension" /* RuntimeMode.Extension */;
    }
    /**
     * 检测当前运行模式。
     *
     * 检测逻辑：
     * 1. 如果已被 _forceExtensionMode() 强制设置，直接返回 Extension
     * 2. 如果 window !== window.parent 且 window.parent 可访问，说明在 iframe 中 → Userscript
     * 3. 否则 → Extension（主窗口环境）
     */
    function detectRuntimeMode() {
        if (_cachedMode !== null)
            return _cachedMode;
        try {
            // 如果 window.parent 存在且不等于 window，说明在 iframe 中
            if (typeof window.parent !== 'undefined' && window.parent !== window) {
                // 尝试访问 parent 的属性，确认不是跨域 iframe
                void window.parent.document;
                _cachedMode = "userscript" /* RuntimeMode.Userscript */;
            }
            else {
                _cachedMode = "extension" /* RuntimeMode.Extension */;
            }
        }
        catch (e) {
            // 跨域 iframe 访问 parent.document 会抛错，这种情况不太可能出现在酒馆环境
            // 保守地认为是油猴脚本模式
            _cachedMode = "userscript" /* RuntimeMode.Userscript */;
        }
        return _cachedMode;
    }
    /** 是否为油猴脚本模式 */
    function isUserscriptMode() {
        return detectRuntimeMode() === "userscript" /* RuntimeMode.Userscript */;
    }
    /** 是否为酒馆插件模式 */
    function isExtensionMode() {
        return detectRuntimeMode() === "extension" /* RuntimeMode.Extension */;
    }
    /**
     * 获取酒馆主窗口引用。
     *
     * - 油猴脚本模式：返回 window.parent（酒馆主窗口）
     * - 插件模式：返回 window（自身就是主窗口）
     */
    function getHostWindow() {
        if (typeof window === 'undefined') {
            return globalThis;
        }
        if (isUserscriptMode()) {
            try {
                return window.parent || window;
            }
            catch (e) {
                return window;
            }
        }
        return window;
    }
    /**
     * 检查是否已有另一个实例在运行（互斥检测）。
     * 如果已有实例，返回 true（应跳过初始化）。
     * 如果没有，标记当前实例并返回 false。
     */
    function checkAndMarkInstance() {
        const hostWin = getHostWindow();
        if (hostWin[ACU_INSTANCE_FLAG]) {
            console.warn('[SP·数据库 V] 检测到另一个实例已在运行，跳过初始化。请勿同时安装油猴脚本和酒馆插件。');
            return true; // 已有实例
        }
        hostWin[ACU_INSTANCE_FLAG] = true;
        return false; // 首个实例
    }

    /**
     * shared/constants.ts — 环境常量
     *
     * 纯常量定义，不依赖运行时环境。
     * 从 src/core/01_header_and_env.js 迁移而来。
     */
    /** 调试模式开关（控制 console.log 输出，不影响日志缓冲区） */
    const DEBUG_MODE_ACU = false;
    /**
     * 唯一脚本标识符
     * 重要：如需创建独立副本，请修改此值为全新的唯一英文名称
     */
    const UNIQUE_SCRIPT_ID = 'shujuku_v120';
    /** 脚本 ID 前缀（等同于 UNIQUE_SCRIPT_ID） */
    const SCRIPT_ID_PREFIX_ACU = UNIQUE_SCRIPT_ID;
    /** 主弹窗 ID */
    const POPUP_ID_ACU = `${SCRIPT_ID_PREFIX_ACU}-popup`;
    /** 菜单项 ID */
    const MENU_ITEM_ID_ACU = `${SCRIPT_ID_PREFIX_ACU}-menu-item`;
    // ═══ 从 import-status-ui.ts 迁移的纯常量/纯函数 ═══
    const IMPORTED_ENTRY_PREFIX_ACU$1 = 'TavernDB-ACU-ImportedTxt-';
    function getImportStablePrefix_ACU$1() { return '外部导入-'; }
    function getImportBatchPrefix_ACU$1() { return getImportStablePrefix_ACU$1(); }
    function getImportJsonStorageComment_ACU$1(modeSuffix = '-Selected') {
        const IMPORT_PREFIX = '外部导入-';
        return `${IMPORT_PREFIX}TavernDB-ACU-ImportedJsonData${modeSuffix}`;
    }
    // ═══ 从 toast.ts 迁移的纯常量 ═══
    const ACU_TOAST_CATEGORY_ACU = {
        ERROR: 'error',
        TABLE_OK: 'table_ok',
        PLAN_OK: 'plan_ok',
        PLANNING: 'planning',
        MANUAL_TABLE: 'manual_table',
        MERGE_TABLE: 'merge_table',
        IMPORT: 'import',
    };
    const TABLE_ORDER_FIELD_ACU = 'orderNo';

    /**
     * shared/env.ts — 运行时环境检测与存储策略
     *
     * 从 src/core/01_header_and_env.js 迁移而来。
     * 提供顶层窗口引用、存储策略常量和 NO-OP 存储后端。
     */
    /** 顶层窗口引用（油猴模式下为 window.parent，插件模式下为 window） */
    const topLevelWindow_ACU = getHostWindow();
    /** 是否禁止使用浏览器 localStorage/sessionStorage 存储配置 */
    const FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU = true;
    /** 是否允许从旧 localStorage 迁移设置到酒馆设置（迁移后仍不再写 localStorage） */
    const ALLOW_LEGACY_LOCALSTORAGE_MIGRATION_ACU = false;
    /** 仅用于"可选迁移"读取旧 localStorage，不是配置持久化后端 */
    let legacyLocalStorage_ACU = null;
    try {
        legacyLocalStorage_ACU = topLevelWindow_ACU.localStorage;
    }
    catch (e) {
        legacyLocalStorage_ACU = null;
    }
    /**
     * storage_ACU：旧代码里大量把它当作"配置存储"。
     * 现在默认是一个 NO-OP 存储，避免任何本地持久化。
     * 真实持久化后端请走 getConfigStorage_ACU()。
     */
    let storage_ACU = {
        getItem: () => null,
        setItem: () => { },
        removeItem: () => { }
    };
    if (!FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU) {
        try {
            storage_ACU = topLevelWindow_ACU.localStorage;
        }
        catch (e) {
            console.error('[AutoCardUpdater] localStorage is not available. Settings will not be saved.', e);
            storage_ACU = { getItem: () => null, setItem: () => { }, removeItem: () => { } };
        }
    }

    /**
     * 全局数据表 — 默认表定义
     */
    const globalStateSheet = {
        uid: "sheet_dCudvUnH",
        name: "全局数据表",
        sourceData: {
            note: "记录当前主角所在地点及时间相关参数。此表有且仅有一行。\n- 列1: 主角当前所在地点 - 主角当前所在的具体场景名称。\n- 列2: 当前时间 - 游戏世界的当前时间。格式：\u201CYYYY-MM-DD HH:MM\u201D，初始化时如果剧情没有明确具体的日期和时间，则必须根据世界观和设定自行设定一个明确的日期时间。\n- 列3: 上轮场景时间 - 上一轮交互结束时的时间。\n- 列4: 经过的时间 - 根据当前与上轮时间计算得出的文本描述（如：\u201C几分钟\u201D）。",
            initNode: "插入一条关于当前世界状态的记录。",
            deleteNode: "禁止删除。",
            updateNode: "当主角从当前所在区域离开时，更新所在地点。每轮必须更新时间。\nSQL示例: UPDATE global_state SET current_location = '新地点', prev_scene_time = cur_time, cur_time = '2024-03-15 16:00', elapsed_time = '约1小时' WHERE row_id = 1;",
            insertNode: "禁止操作。",
            ddl: `CREATE TABLE global_state ( -- 全局数据表
  row_id INTEGER PRIMARY KEY, -- 行号
  current_location TEXT NOT NULL, -- 主角当前所在地点
  cur_time TEXT NOT NULL CHECK(cur_time GLOB '????-??-?? ??:??'), -- 当前时间
  prev_scene_time TEXT CHECK(prev_scene_time IS NULL OR prev_scene_time GLOB '????-??-?? ??:??'), -- 上轮场景时间
  elapsed_time TEXT -- 经过的时间
);`
        },
