    const inventorySheet = {
        uid: "sheet_in05z9vz",
        name: "背包物品表",
        sourceData: {
            note: "记录主角拥有的所有物品、装备。\n- 列1: 物品名称 - 物品的名称。\n- 列2: 数量 - 拥有的数量。\n- 列3: 描述/效果 - 物品的功能或背景描述。\n- 列4: 类别 - 物品的类别（如：\u201C武器\u201D、\u201C消耗品\u201D、\u201C杂物\u201D）。",
            initNode: "游戏初始化时，根据剧情与设定添加主角的初始携带物品。",
