    /**
     * 数据隔离（Isolation）相关函数
     *
     * 管理数据隔离标识的历史记录、Profile 创建和切换。
     */
    const MAX_DATA_ISOLATION_HISTORY = 20;
    function normalizeDataIsolationHistory_ACU(list) {
        const seen = new Set();
        const cleaned = [];
        const sourceList = list !== undefined ? list : globalMeta_ACU.isolationCodeList;
        if (Array.isArray(sourceList)) {
            sourceList.forEach((code) => {
                if (typeof code !== 'string')
                    return;
                const trimmed = code.trim();
                if (!trimmed || seen.has(trimmed))
                    return;
                seen.add(trimmed);
                cleaned.push(trimmed);
            });
        }
        globalMeta_ACU.isolationCodeList = cleaned.slice(0, MAX_DATA_ISOLATION_HISTORY);
        return globalMeta_ACU.isolationCodeList;
    }
    function getDataIsolationHistory_ACU() {
        return normalizeDataIsolationHistory_ACU();
    }
    function addDataIsolationHistory_ACU(code, { save = true } = {}) {
        if (typeof code !== 'string')
            return;
        const trimmed = code.trim();
        if (!trimmed)
            return;
        const history = getDataIsolationHistory_ACU();
        globalMeta_ACU.isolationCodeList = [trimmed, ...history.filter((item) => item !== trimmed)].slice(0, MAX_DATA_ISOLATION_HISTORY);
        if (save)
            saveGlobalMeta_ACU();
    }
    function removeDataIsolationHistory_ACU(code, { save = true } = {}) {
        if (typeof code !== 'string')
            return;
        const history = getDataIsolationHistory_ACU();
        globalMeta_ACU.isolationCodeList = history.filter((item) => item !== code);
        if (save)
            saveGlobalMeta_ACU();
    }
    function ensureProfileExists_ACU(code, { seedFromCurrent = true, settings = {} } = {}) {
        const c = normalizeIsolationCode_ACU(code);
        const hasSettings = !!readProfileSettingsFromStorage_ACU(c);
        const hasTemplate = !!readProfileTemplateFromStorage_ACU(c);
        if (!hasSettings) {
            const seed = seedFromCurrent ? sanitizeSettingsForProfileSave_ACU(settings) : {};
            seed.dataIsolationCode = c;
            try {
                writeProfileSettingsToStorage_ACU(c, seed);
            }
            catch (e) {
                logWarn_ACU('[Profile] seed settings failed:', e);
            }
        }
        if (!hasTemplate) {
            const seedTemplate = seedFromCurrent ? (TABLE_TEMPLATE_ACU || DEFAULT_TABLE_TEMPLATE_ACU) : DEFAULT_TABLE_TEMPLATE_ACU;
            try {
                writeProfileTemplateToStorage_ACU(c, seedTemplate);
            }
            catch (e) {
                logWarn_ACU('[Profile] seed template failed:', e);
            }
        }
    }
