            while ((match = parenRegex.exec(expr)) !== null) {
                const innerExpr = match[1];
                const innerResult = processExpression(innerExpr);
                processed = processed.replace(match[0], `__PAREN_${idx}__`);
                _parenResults[`__PAREN_${idx}__`] = innerResult;
                idx++;
