        logDebug_ACU('[剧情推进] [Plot] getPlotFromHistory_ACU 被调用，聊天记录长度:', chat?.length || 0, '，检索选项:', options || {});
        if (!chat || chat.length === 0) {
            logDebug_ACU('[剧情推进] [Plot] 聊天记录为空');
            return '';
        }
        const currentPresetName = getCurrentRuntimePlotPresetName_ACU({ fallbackToGlobal: true });
        logDebug_ACU('[剧情推进] [Plot] 当前聊天实际预设名称:', currentPresetName || '(默认预设)');
        const upperBound = getPlotHistorySearchUpperBound_ACU(chat, options);
        if (upperBound < 0) {
            logDebug_ACU('[剧情推进] [Plot] 当前楼层之前没有更早的用户消息或可检索范围为空，返回空字符串');
            return '';
        }
        // 如果指定了 taskId，优先从新结构 qrf_plot_tasks 中按任务维度读取
        const targetTaskId = String(options?.taskId || '').trim();
        if (targetTaskId) {
            for (let i = upperBound; i >= 0; i--) {
                const message = chat[i];
                if (message && message.qrf_plot_tasks && typeof message.qrf_plot_tasks === 'object') {
                    const plotPresetName = message.qrf_plot_preset || '';
                    if (currentPresetName !== '' && plotPresetName !== currentPresetName) {
                        continue;
                    }
                    const taskContent = message.qrf_plot_tasks[targetTaskId];
                    if (typeof taskContent === 'string' && taskContent.trim()) {
                        logDebug_ACU(`[剧情推进] [Plot] ✓ 在消息 ${i} 找到任务 "${targetTaskId}" 的 qrf_plot_tasks 数据，长度: ${taskContent.length}`);
                        return taskContent;
                    }
                }
            }
            // 任务级新结构未找到，回退到旧结构
            logDebug_ACU(`[剧情推进] [Plot] 任务 "${targetTaskId}" 在 qrf_plot_tasks 中未找到，回退到旧 qrf_plot 结构。`);
        }
        let latestPlotContent = '';
        let latestPlotIndex = -1;
        for (let i = upperBound; i >= 0; i--) {
            const message = chat[i];
            if (message && message.qrf_plot) {
                const plotPresetName = message.qrf_plot_preset || '';
                if (currentPresetName === '') {
                    latestPlotContent = message.qrf_plot;
                    latestPlotIndex = i;
                    logDebug_ACU(`[剧情推进] [Plot] (无预设模式) ✓ 在消息 ${i} 找到最新的plot数据，检索上界: ${upperBound}`);
                    break;
                }
                if (plotPresetName === currentPresetName) {
                    latestPlotContent = message.qrf_plot;
                    latestPlotIndex = i;
                    logDebug_ACU(`[剧情推进] [Plot] ✓ 在消息 ${i} (is_user=${message.is_user}) 找到精确匹配预设 "${currentPresetName}" 的plot数据，检索上界: ${upperBound}`);
                    break;
                }
            }
        }
        if (!latestPlotContent && currentPresetName !== '') {
            logDebug_ACU(`[剧情推进] [Plot] 未找到精确匹配预设 "${currentPresetName}" 的数据，尝试在上界 ${upperBound} 之前寻找无标签旧数据...`);
            for (let i = upperBound; i >= 0; i--) {
                const message = chat[i];
                if (message && message.qrf_plot) {
                    const plotPresetName = message.qrf_plot_preset || '';
                    if (plotPresetName === '') {
                        latestPlotContent = message.qrf_plot;
                        latestPlotIndex = i;
                        logDebug_ACU(`[剧情推进] [Plot] (兼容模式) ✓ 在消息 ${i} 找到无标签的旧plot数据作为回退，检索上界: ${upperBound}`);
                        break;
                    }
                }
            }
        }
        if (latestPlotContent) {
            logDebug_ACU(`[剧情推进] [Plot] 返回匹配预设 "${currentPresetName || '(无)'}" 的最新剧情规划数据，消息索引: ${latestPlotIndex}, 检索上界: ${upperBound}, 长度: ${latestPlotContent.length}`);
            return latestPlotContent;
        }
        logDebug_ACU(`[剧情推进] [Plot] 未找到匹配预设 "${currentPresetName || '(无)'}" 的plot数据，检索上界: ${upperBound}`);
        return '';
    }
    /**
     * 将plot附加到对应的用户消息上。
     * 使用用户输入文本哈希精确匹配，避免保存到错误的楼层。
     */
    async function savePlotToLatestMessage_ACU(force = false) {
        logDebug_ACU('[剧情推进] [Plot] savePlotToLatestMessage_ACU 被调用');
        logDebug_ACU('[剧情推进] [Plot] planningGuard_ACU.inProgress:', planningGuard_ACU.inProgress);
        logDebug_ACU('[剧情推进] [Plot] planningGuard_ACU.ignoreNextGenerationEndedCount:', planningGuard_ACU.ignoreNextGenerationEndedCount);
        logDebug_ACU('[剧情推进] [Plot] tempPlotToSave_ACU:', tempPlotToSave_ACU ? (typeof tempPlotToSave_ACU === 'string' ? `长度=${tempPlotToSave_ACU.length}` : `content长度=${tempPlotToSave_ACU.content?.length}, hash=${tempPlotToSave_ACU.userInputHash}`) : '(空)');
        if (!force && planningGuard_ACU.inProgress) {
            logDebug_ACU('[剧情推进] [Plot] Planning in progress, ignoring GENERATION_ENDED.');
            return;
        }
        if (planningGuard_ACU.ignoreNextGenerationEndedCount > 0) {
            planningGuard_ACU.ignoreNextGenerationEndedCount--;
            logDebug_ACU(`[剧情推进] [Plot] Ignoring planning-triggered GENERATION_ENDED (${planningGuard_ACU.ignoreNextGenerationEndedCount} left).`);
            return;
        }
        if (!tempPlotToSave_ACU) {
            logDebug_ACU('[剧情推进] [Plot] tempPlotToSave_ACU 为空，无需保存');
            return;
        }
        let plotContent, userInputHash, userInputText;
        if (typeof tempPlotToSave_ACU === 'string') {
            plotContent = tempPlotToSave_ACU;
            userInputHash = null;
            userInputText = null;
            logDebug_ACU('[剧情推进] [Plot] 检测到旧格式数据，使用回退匹配逻辑');
        }
        else {
            plotContent = tempPlotToSave_ACU.content;
            userInputHash = tempPlotToSave_ACU.userInputHash;
            userInputText = tempPlotToSave_ACU.userInputText;
            logDebug_ACU('[剧情推进] [Plot] 使用新格式，用户输入哈希:', userInputHash, '，原始文本长度:', userInputText?.length || 0);
        }
        if (!plotContent) {
            logWarn_ACU('[剧情推进] [Plot] plotContent 为空，无法保存');
            _set_tempPlotToSave_ACU(null);
            return;
        }
        const MAX_POLL_ATTEMPTS = 20;
        const POLL_INTERVAL_MS = 100;
        let pollAttempts = 0;
        let target = null;
        const tryFindTarget = () => {
            const chat = getChatArray_ACU();
            if (!chat || chat.length === 0) {
                return null;
            }
            if (userInputHash) {
                for (let i = chat.length - 1; i >= 0; i--) {
                    const msg = chat[i];
                    if (msg && msg.is_user) {
                        if (msg._qrf_plot_pending_hash === userInputHash) {
                            delete msg._qrf_plot_pending_hash;
                            if (!msg.qrf_plot) {
                                logDebug_ACU(`[剧情推进] [Plot] ✓ 通过消息对象上的哈希标记找到目标用户消息（索引 ${i}，哈希: ${userInputHash}）`);
                                return { msg, index: i };
                            }
                            else {
                                logDebug_ACU(`[剧情推进] [Plot] 索引 ${i} 的消息哈希标记匹配但已有plot，继续查找`);
                            }
                        }
                        const msgText = msg.mes || '';
                        const msgHash = hashUserInput_ACU(msgText);
                        if (msgHash === userInputHash) {
                            if (!msg.qrf_plot) {
                                logDebug_ACU(`[剧情推进] [Plot] ✓ 通过消息文本哈希精确匹配找到目标用户消息（索引 ${i}，哈希: ${userInputHash}）`);
                                return { msg, index: i };
                            }
                            else {
                                logDebug_ACU(`[剧情推进] [Plot] 索引 ${i} 的消息哈希匹配但已有plot，继续查找`);
                            }
                        }
                    }
                }
            }
            for (let i = chat.length - 1; i >= 0; i--) {
                const msg = chat[i];
                if (msg && msg.is_user && !msg.qrf_plot) {
                    logDebug_ACU(`[剧情推进] [Plot] 使用回退逻辑找到目标用户消息于索引 ${i}`);
                    return { msg, index: i };
                }
            }
            return null;
        };
        const pollForTarget = () => {
            pollAttempts++;
            const result = tryFindTarget();
            if (result) {
                target = result.msg;
                logDebug_ACU(`[剧情推进] [Plot] 在第 ${pollAttempts} 次轮询中找到目标消息`);
                target.qrf_plot = plotContent;
                const currentPresetName = getCurrentRuntimePlotPresetName_ACU({ fallbackToGlobal: true });
                target.qrf_plot_preset = currentPresetName;
                // 同时写入任务级结果映射 qrf_plot_tasks
                if (typeof tempPlotToSave_ACU === 'object' && tempPlotToSave_ACU !== null) {
                    const taskResults = tempPlotToSave_ACU.taskResults;
                    if (Array.isArray(taskResults) && taskResults.length > 0) {
                        if (!target.qrf_plot_tasks || typeof target.qrf_plot_tasks !== 'object') {
                            target.qrf_plot_tasks = {};
                        }
                        for (const result of taskResults) {
                            if (result && result.success && result.taskId && typeof result.rawResponse === 'string' && result.rawResponse.trim()) {
                                target.qrf_plot_tasks[result.taskId] = result.rawResponse.trim();
                            }
                        }
                    }
                }
                logDebug_ACU('[剧情推进] [Plot] ✓ Plot数据已精确附加到目标用户消息，长度:', plotContent.length, '，预设:', currentPresetName || '(默认预设)');
                _set_tempPlotToSave_ACU(null);
                return true;
            }
            if (pollAttempts >= MAX_POLL_ATTEMPTS) {
                logWarn_ACU(`[剧情推进] [Plot] 轮询 ${MAX_POLL_ATTEMPTS} 次后仍未找到目标用户消息。用户输入哈希: ${userInputHash || '(无)'}，原始文本: ${userInputText ? `长度=${userInputText.length}` : '(无)'}。将在下一次事件中重试。`);
                return false;
            }
            setTimeout(pollForTarget, POLL_INTERVAL_MS);
            return null;
        };
        setTimeout(() => {
            pollForTarget();
        }, 100);
    }

    /**
     * data/gateways/host-state-gateway.ts — 宿主运行时状态访问网关
     *
     * 封装 SillyTavern_API_ACU 上的只读运行时属性访问：
     *   - 用户名 (name1)
     *   - 用户人设描述 (persona_description)
     *   - 当前角色数据 (characters[this_chid]) 的 fallback 链
     *
     * service 层通过本模块访问宿主运行时状态，不再直接读取 SillyTavern_API_ACU 的属性。
     * 所有方法内置空值防御，宿主 API 不可用时返回安全默认值。
     */
    /**
     * 获取当前用户名
     * 优先级：SillyTavern_API_ACU.name1 → 默认值 '用户'
     * @returns 用户名字符串
     */
    function getUserName_ACU() {
        return SillyTavern_API_ACU?.name1 || '用户';
    }
    /**
     * 获取用户人设描述 (persona_description)
     * 按优先级尝试多个来源：
     *   1. SillyTavern.getContext().powerUserSettings.persona_description
     *   2. window.power_user.persona_description
     *   3. SillyTavern_API_ACU.powerUserSettings.persona_description
     * @param win 可选，指定查找 SillyTavern.getContext() 的 window 对象（支持 iframe 场景）
     * @returns 人设描述字符串，不可用时返回 ''
     */
    function getPersonaDescription_ACU(win) {
        try {
            const w = win || topLevelWindow_ACU || window;
            const stContext = w?.SillyTavern?.getContext?.();
            return stContext?.powerUserSettings?.persona_description
                || w?.power_user?.persona_description
                || SillyTavern_API_ACU?.powerUserSettings?.persona_description
                || '';
        }
        catch {
            return '';
        }
    }
    /**
     * 获取当前角色数据（带完整 fallback 链）
     * 按优先级尝试多个来源：
     *   1. TavernHelper.getCharData('current')（通过 character-gateway）
     *   2. SillyTavern_API_ACU.characters[this_chid]
     *   3. SillyTavern.getContext().characters[characterId]
     *   4. window.characters[window.this_chid]（全局变量 fallback）
     * @param win 可选，指定查找全局变量的 window 对象（支持 iframe 场景）
     * @returns 角色数据对象，不可用时返回 null
     */
    function getCurrentCharacterFallback_ACU(win) {
        try {
            // 优先使用 TavernHelper.getCharData('current')
            const charData = getCurrentCharData_ACU();
            if (charData) {
                return getCurrentCharData_ACU('current') || charData;
            }
            const w = win || topLevelWindow_ACU || window;
            const stContext = w?.SillyTavern?.getContext?.();
            return SillyTavern_API_ACU?.characters?.[SillyTavern_API_ACU?.this_chid]
                || stContext?.characters?.[stContext?.characterId]
                || (typeof w?.characters !== 'undefined' && typeof w?.this_chid !== 'undefined'
                    ? w.characters[w.this_chid]
                    : null);
        }
        catch {
            return null;
        }
    }
    /**
     * 获取当前角色描述文本
     * 在 getCurrentCharacterFallback_ACU 基础上提取描述字段，
     * 并额外尝试 stContext.name2_description 作为最终 fallback。
     * @param win 可选，指定查找的 window 对象
     * @returns 角色描述字符串，不可用时返回 ''
     */
    function getCharDescription_ACU(win) {
        try {
            const character = getCurrentCharacterFallback_ACU(win);
            if (character?.description || character?.data?.description) {
                return character.description || character.data.description;
            }
            // 最终 fallback：stContext.name2_description
            const w = win || topLevelWindow_ACU || window;
            const stContext = w?.SillyTavern?.getContext?.();
            return stContext?.name2_description || '';
        }
        catch {
            return '';
        }
    }

    /**
     * service/ai/prompt-builder/prompt-prepare.ts
     * AI 输入准备 — 格式化表格数据和对话内容为 AI 可读文本
     * 从 prompt-builder.ts 拆出（L14-L194）
     */
    async function resolvePromptSourceTableData_ACU(options, sqlMode) {
        if (!sqlMode) {
            return options?.tableData || currentJsonTableData_ACU;
        }
        try {
            const provider = await ensureStorageProviderReady_ACU();
            if (provider.mode !== 'sqlite') {
                logError_ACU(`prepareAIInput_ACU: SQLite mode expected runtime DB provider, got ${provider.mode}.`);
                return null;
            }
            return provider.getCurrentData();
        }
        catch (e) {
            logError_ACU('prepareAIInput_ACU: 无法从 SQLite 运行时 DB 获取权威表格数据。', e);
            return null;
        }
    }
    async function prepareAIInput_ACU(messages, updateMode = 'standard', targetSheetKeys = null, options = {}) {
        const sqlMode = isSqliteMode();
        const sourceTableData = await resolvePromptSourceTableData_ACU(options, sqlMode);
        if (!sourceTableData) {
            logError_ACU(sqlMode
                ? 'prepareAIInput_ACU: Cannot prepare AI input, SQLite runtime DB data is null.'
                : 'prepareAIInput_ACU: Cannot prepare AI input, currentJsonTableData_ACU is null.');
            return null;
        }
        let _seedGuideDataForThisPrepare_ACU = null;
        let workingTableData = sourceTableData;
        try {
            if (!sqlMode) {
                _seedGuideDataForThisPrepare_ACU = await ensureChatSheetGuideSeeded_ACU({ reason: 'prepare_ai_input_seedrows' });
                if (_seedGuideDataForThisPrepare_ACU) {
                    if (options?.tableData) {
                        workingTableData = JSON.parse(JSON.stringify(sourceTableData));
                        Object.keys(workingTableData).forEach((sheetKey) => {
                            if (!sheetKey.startsWith('sheet_'))
                                return;
                            const table = workingTableData[sheetKey];
                            if (!table || typeof table !== 'object')
                                return;
                            const existing = table?.seedRows;
                            if (Array.isArray(existing) && existing.length > 0)
                                return;
                            const seedRows = _seedGuideDataForThisPrepare_ACU?.[sheetKey]?.seedRows;
                            if (Array.isArray(seedRows) && seedRows.length > 0) {
                                table.seedRows = JSON.parse(JSON.stringify(seedRows));
                            }
                        });
                    }
                    else {
                        attachSeedRowsToCurrentDataFromGuide_ACU(_seedGuideDataForThisPrepare_ACU);
                    }
                }
            }
        }
        catch (e) {
            logWarn_ACU('[AI输入准备] ensureChatSheetGuideSeeded 失败, seed rows 可能不完整:', e);
        }
        let tableDataText = '';
        let _seedRowsTablesUsed_ACU = [];
        const tableIndexes = getSortedSheetKeys_ACU(workingTableData);
        tableIndexes.forEach((sheetKey, tableIndex) => {
            const table = workingTableData[sheetKey];
            if (!table || !table.name || !table.content)
                return;
            if (targetSheetKeys && Array.isArray(targetSheetKeys)) {
                if (!targetSheetKeys.includes(sheetKey))
                    return;
            }
            const isSummaryTable = isSummaryOrOutlineTable_ACU(table.name);
            let shouldShowData = true;
            if (!targetSheetKeys) {
                const isUnifiedMode = (updateMode === 'full' || updateMode === 'manual_unified' || updateMode === 'auto_unified');
                const isStandardMode = (updateMode === 'standard' || updateMode === 'auto_standard' || updateMode === 'manual_standard');
                const isSummaryMode = (updateMode === 'summary' || updateMode === 'auto_summary_silent' || updateMode === 'manual_summary');
                if (isUnifiedMode) {
                    shouldShowData = true;
                }
                else if (isStandardMode && isSummaryTable) {
                    shouldShowData = false;
                }
                else if (isSummaryMode && !isSummaryTable) {
                    shouldShowData = false;
                }
            }
            if (!shouldShowData) {
                return;
            }
            // SQLite 模式：输出 DDL + 注释数据格式；数据只来自运行时 DB，不再从模板 seedRows 兜底。
            if (sqlMode && table.sourceData?.ddl) {
                tableDataText += formatTableForSqliteMode(table, tableIndex, sheetKey, _seedGuideDataForThisPrepare_ACU, { allowSeedRowsFallback: false });
                return;
            }
            const allRows = table.content.slice(1);
            const seedRows = sqlMode ? [] : getEffectiveSeedRowsForSheet_ACU(sheetKey, { guideData: _seedGuideDataForThisPrepare_ACU, allowTemplateFallback: true });
            try {
                if ((!Array.isArray(table.seedRows) || table.seedRows.length === 0) && Array.isArray(seedRows) && seedRows.length > 0) {
                    table.seedRows = JSON.parse(JSON.stringify(seedRows));
                }
            }
            catch (e) { }
            const isUsingSeedRows = (allRows.length === 0 && seedRows.length > 0);
            if (isUsingSeedRows) {
                try {
                    _seedRowsTablesUsed_ACU.push(String(table.name || sheetKey));
                }
                catch (e) { }
            }
            const effectiveAllRows = (allRows.length > 0) ? allRows : (seedRows.length > 0 ? seedRows : []);
            if (effectiveAllRows.length === 0) {
                tableDataText += `[${tableIndex}:${table.name}]\n`;
                // [修复] 列头编号使用 0 基索引，与原生 DSL insertRow/updateRow 的对象键语义一致。
                // 原先使用 i + 1 导致列头标注为 [1:列名],[2:列名]...，
                // 而默认提示词示例使用 {"0":"...","1":"..."} 的 0 基格式，
                // 模型会把列头编号 "1" 跟对象键 "1" 做映射，导致所有数据整体右移一列。
                const headers = table.content[0] ? table.content[0].slice(1).map((h, i) => `[${i}:${h}]`).join(', ') : 'No Headers';
                tableDataText += `  Columns: ${headers}\n`;
                if (table.sourceData) {
                    tableDataText += `  - Note: ${table.sourceData.note || 'N/A'}\n`;
                    const initNodeContent = table.sourceData.initNode || table.sourceData.insertNode || 'N/A';
                    tableDataText += `  - Init Trigger: ${initNodeContent}\n`;
                }
                tableDataText += `  (该表格为空，请进行初始化。)\n\n`;
            }
            else {
                tableDataText += `[${tableIndex}:${table.name}]\n`;
                // [修复] 同上——列头编号 0 基，与原生 DSL 对象键语义对齐
                const headers = table.content[0] ? table.content[0].slice(1).map((h, i) => `[${i}:${h}]`).join(', ') : 'No Headers';
                tableDataText += `  Columns: ${headers}\n`;
                if (table.sourceData) {
                    tableDataText += `  - Note: ${table.sourceData.note || 'N/A'}\n`;
                    tableDataText += `  - Insert Trigger: ${table.sourceData.insertNode || table.sourceData.initNode || 'N/A'}\n`;
                    tableDataText += `  - Update Trigger: ${table.sourceData.updateNode || 'N/A'}\n`;
                    tableDataText += `  - Delete Trigger: ${table.sourceData.deleteNode || 'N/A'}\n`;
                }
                if (isUsingSeedRows) {
                    tableDataText += `  - SeedRows: 已提供模板基础数据（尚未写入聊天楼层数据；本次填表可直接基于这些行更新）\n`;
                }
                let rowsToProcess = effectiveAllRows;
                let startIndex = 0;
                const isSummaryTable = (table.name.trim() === '纪要表' || table.name.trim() === '总结表');
                if (isSummaryTable && effectiveAllRows.length > 10) {
                    startIndex = effectiveAllRows.length - 10;
                    rowsToProcess = effectiveAllRows.slice(-10);
                    tableDataText += `  - Note: Showing last ${rowsToProcess.length} of ${effectiveAllRows.length} entries (summary table fixed limit).\n`;
                }
                else if (!isSummaryTable) {
                    const sendLatestRows = (table.updateConfig && typeof table.updateConfig.sendLatestRows === 'number')
                        ? table.updateConfig.sendLatestRows : -1;
                    if (sendLatestRows > 0 && effectiveAllRows.length > sendLatestRows) {
                        startIndex = effectiveAllRows.length - sendLatestRows;
                        rowsToProcess = effectiveAllRows.slice(-sendLatestRows);
                        tableDataText += `  - Note: Showing last ${rowsToProcess.length} of ${effectiveAllRows.length} entries (sendLatestRows=${sendLatestRows}).\n`;
                    }
                }
                if (rowsToProcess.length > 0) {
                    rowsToProcess.forEach((row, index) => {
                        const originalRowIndex = startIndex + index;
                        const rowData = row.slice(1).join(', ');
                        tableDataText += `  [${originalRowIndex}] ${rowData}\n`;
                    });
                }
                else {
                    tableDataText += '  (No data rows)\n';
                }
                tableDataText += '\n';
            }
        });
        if (_seedRowsTablesUsed_ACU.length > 0) {
            logDebug_ACU(`[SeedRows] $0 使用 seedRows 作为基础数据：${_seedRowsTablesUsed_ACU.join('、')}`);
        }
        let messagesText = '当前最新对话内容:\n';
        if (messages && messages.length > 0) {
            const extractTags = (settings_ACU.tableContextExtractTags || '').trim();
