    async function purgeOldLayerDataCore_ACU() {
        const retainCount = settings_ACU.retainRecentLayers || 0;
        if (retainCount <= 0) {
            logDebug_ACU('[数据清理] retainRecentLayers 为 0 或未设置，跳过清理。');
            return;
        }
        const chat = getChatArray_ACU();
