        const orderedData = prepareOrderedVisualizerData_ACU();
        const orderedKeys = getOrderedSheetKeys_ACU();
        const hasCurrentChat = getChatArray_ACU().length > 0;
        if (scope === 'chat' && !hasCurrentChat) {
