    // 数据管理标签页 HTML生成
    // 承接原data页的数据隔离、删除清理、备份恢复、Medusa合并
    /**
     * 生成数据管理标签页的 HTML 片段
     * 包含：数据隔离、删除与清理、备份与恢复、纪要合并(Medusa)
     */
    function generateDataMgmtTabHTML() {
        return `
                <div id="acu-tab-datamgmt" class="acu-tab-content">
                    <!-- A. 数据隔离 -->
                    <div class="acu-card">
                        <h3>数据隔离</h3>
