                    #${POPUP_ID_ACU} .acu-tab-button {
                        width: 100%;
                        display: flex;
                        align-items: center;
                        justify-content: space-between;
                        gap: 8px;
                        padding: 8px 10px;
                        border: 1px solid transparent;
                        border-radius: 6px;
                        background: transparent;
                        color: var(--acu-text-3);
                        font-size: 12.5px;
                        font-weight: 500;
                        cursor: pointer;
                        transition: all 0.15s ease;
                    }
                    #${POPUP_ID_ACU} .acu-tab-button:hover {
