    function applyAppearance(option) {
        const doc = getAcuHostDocument();
        let style = doc.getElementById(APPEARANCE_STYLE_NODE_ID);
        if (!style) {
            style = doc.createElement('style');
            style.id = APPEARANCE_STYLE_NODE_ID;
            doc.head.appendChild(style);
        }
        style.textContent = buildCss(option);
        const root = doc.getElementById(APP_ROOT_ID);
        if (root) {
            root.style.setProperty('--acu-ui-scale', option.cssScale);
            root.setAttribute('data-acu-ui-scale', option.value);
        }
    }
    /** 仅供测试：清掉注入的样式节点与根节点标记。 */
    function __resetAppearanceInjectorForTests() {
        const doc = getAcuHostDocument();
        doc.getElementById(APPEARANCE_STYLE_NODE_ID)?.remove();
        const root = doc.getElementById(APP_ROOT_ID);
        if (root) {
            root.style.removeProperty('--acu-ui-scale');
            root.removeAttribute('data-acu-ui-scale');
        }
    }

    const SVG_NS = 'http://www.w3.org/2000/svg';
    const MATHML_NS = 'http://www.w3.org/1998/Math/MathML';
    let cachedRenderer = null;
    const trustedHtmlPolicies = new WeakMap();
    function toTrustedHtml(doc, content) {
        const trustedTypesApi = doc.defaultView?.trustedTypes;
        if (!trustedTypesApi)
            return content;
        const existingPolicy = trustedHtmlPolicies.get(doc);
        if (existingPolicy)
            return existingPolicy.createHTML(content);
        try {
            const policy = (trustedTypesApi
                .createPolicy('acu-v2-vue', { createHTML: (value) => value }));
            trustedHtmlPolicies.set(doc, policy);
            return policy.createHTML(content);
        }
        catch {
            return content;
        }
    }
    function createHostNodeOps(doc) {
        return {
            ...nodeOps,
            createElement: (tag, namespace, is, props) => {
                const el = namespace === 'svg'
                    ? doc.createElementNS(SVG_NS, tag)
                    : namespace === 'mathml'
                        ? doc.createElementNS(MATHML_NS, tag)
                        : is
                            ? doc.createElement(tag, { is })
                            : doc.createElement(tag);
                if (tag === 'select' && props && props.multiple != null) {
                    el.setAttribute('multiple', props.multiple);
                }
                return el;
            },
            createText: text => doc.createTextNode(text),
            createComment: text => doc.createComment(text),
            querySelector: selector => doc.querySelector(selector),
            insertStaticContent(content, parent, anchor, namespace, start, end) {
                const before = anchor ? anchor.previousSibling : parent.lastChild;
                if (start && (start === end || start.nextSibling)) {
                    let node = start;
                    while (node) {
                        parent.insertBefore(node.cloneNode(true), anchor);
                        if (node === end)
                            break;
                        node = node.nextSibling;
                    }
                }
                else {
                    const templateContainer = doc.createElement('template');
                    templateContainer.innerHTML = toTrustedHtml(doc, namespace === 'svg'
                        ? `<svg>${content}</svg>`
                        : namespace === 'mathml'
                            ? `<math>${content}</math>`
                            : content);
                    const template = templateContainer.content;
                    if (namespace === 'svg' || namespace === 'mathml') {
                        const wrapper = template.firstChild;
                        if (wrapper) {
                            while (wrapper.firstChild)
                                template.appendChild(wrapper.firstChild);
                            template.removeChild(wrapper);
                        }
                    }
                    parent.insertBefore(template, anchor);
