    // ═══════════════════════════════════════════════════════════════
    $(function () {
        // 互斥检测：如果已有实例（插件或另一个油猴脚本）在运行，跳过初始化
        if (checkAndMarkInstance()) {
            console.warn('[SP·数据库 V] 油猴脚本检测到已有实例运行，跳过初始化。');
            return;
        }
        console.log('ACU_INIT_DEBUG: Document is ready, attempting to initialize ACU script (Userscript mode).');
        mainInitialize_ACU();
        bootstrapAcuV2();
    });

